/*
 * Journal ("Deník"): every piece of syntax the app ran, whether typed, pasted or generated by a
 * dialog, so a session can be reproduced or turned into a syntax file.
 * SPDX-License-Identifier: GPL-3.0-or-later
 */
import { create } from 'zustand';

export type JournalSource = 'syntax' | 'dialog' | 'menu' | 'data' | 'system';

export interface JournalEntry {
  time: number;
  source: JournalSource;
  specId?: string;
  values?: Record<string, unknown>;
  syntax: string;
  ok: boolean;
}

const MAX = 1000;

interface JournalState {
  entries: JournalEntry[];
  add: (e: JournalEntry) => void;
  clear: () => void;
  load: (entries: JournalEntry[]) => void;
  /** All journal syntax as one runnable file. */
  toSyntax: () => string;
}

export const useJournal = create<JournalState>((set, get) => ({
  entries: [],
  add: (e) => set({ entries: [...get().entries.slice(-MAX + 1), e] }),
  clear: () => set({ entries: [] }),
  load: (entries) => set({ entries }),
  toSyntax: () =>
    get()
      .entries.map((e) => `* ${new Date(e.time).toLocaleString()}${e.specId ? ` (${e.specId})` : ''}${e.ok ? '' : ' [chyba/error]'}.\n${e.syntax.trim()}\n`)
      .join('\n'),
}));
